import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

function RoleSelection() {
  const navigate = useNavigate();
  const [role, setRole] = useState("");
  const [subRole, setSubRole] = useState("");
  const [customPurpose, setCustomPurpose] = useState("");
  const [error, setError] = useState("");

  // Sub-options
  const professionalOptions = ["Student", "Software Engineer", "Teacher", "Doctor", "Lawyer"];
  const homemakerOptions = ["Parent", "Caregiver", "House Manager", "Volunteer"];

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        setError("You must be logged in first!");
        return;
      }

      await axios.put(
        "http://localhost:5000/api/users/role",
        { 
          role, 
          subRole: role === "Customize Purpose" ? customPurpose : subRole 
        },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      navigate("/dashboard"); // after role selection
    } catch (err) {
      setError(err.response?.data?.msg || "Something went wrong");
    }
  };

  return (
    <div className="flex justify-center items-center h-screen bg-gray-100">
      <div className="w-full max-w-md bg-white shadow-lg rounded-2xl p-8">
        <h2 className="text-2xl font-bold mb-6 text-center text-gray-700">Select Your Role</h2>
        {error && <p className="text-red-500 text-center">{error}</p>}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Main Role Selection */}
          <select
            value={role}
            onChange={(e) => {
              setRole(e.target.value);
              setSubRole("");
              setCustomPurpose("");
            }}
            className="w-full px-4 py-2 border rounded-lg focus:ring focus:ring-blue-300"
            required
          >
            <option value="">-- Select Role --</option>
            <option value="Professional">Professional</option>
            <option value="Homemaker">Homemaker</option>
            <option value="Customize Purpose">Customize Purpose</option>
          </select>

          {/* Sub-Role for Professional */}
          {role === "Professional" && (
            <select
              value={subRole}
              onChange={(e) => setSubRole(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:ring focus:ring-blue-300"
              required
            >
              <option value="">-- Select Sub-Role --</option>
              {professionalOptions.map((opt, idx) => (
                <option key={idx} value={opt}>{opt}</option>
              ))}
            </select>
          )}

          {/* Sub-Role for Homemaker */}
          {role === "Homemaker" && (
            <select
              value={subRole}
              onChange={(e) => setSubRole(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:ring focus:ring-blue-300"
              required
            >
              <option value="">-- Select Sub-Role --</option>
              {homemakerOptions.map((opt, idx) => (
                <option key={idx} value={opt}>{opt}</option>
              ))}
            </select>
          )}

          {/* Custom Purpose */}
          {role === "Customize Purpose" && (
            <input
              type="text"
              value={customPurpose}
              onChange={(e) => setCustomPurpose(e.target.value)}
              placeholder="Enter your purpose"
              className="w-full px-4 py-2 border rounded-lg focus:ring focus:ring-blue-300"
              required
            />
          )}

          {/* Submit Button */}
          <button
            type="submit"
            className="w-full bg-blue-500 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-600 transition"
          >
            Continue
          </button>
        </form>
      </div>
    </div>
  );
}

export default RoleSelection;
